def main():
    n = int(input())
    q = list(map(int, input().split()))
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    am = 10**6
    for i in range(n):
        if a[i] == 0:
            continue
        if am > q[i] // a[i]:
            am = q[i] // a[i]

    bm = 10**6
    for i in range(n):
        if b[i] == 0:
            continue
        if bm > q[i] // b[i]:
            bm = q[i] // b[i]

    ans = 0

    for x in range(am + 1):
        remaining_q = [q[i] - x * a[i] for i in range(n)]
        max_b_servings = 10**6

        for i in range(n):
            if b[i] > 0:
                max_b_servings = min(max_b_servings, remaining_q[i] // b[i])

        ans = max(ans, x + max_b_servings)

    print(ans)
